'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      const promise = Promise.resolve().then(work).then(value => {
        pending.delete(key);
        commit(value);
        return value;
      });
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };
'use strict';

function createClock(ttlMs, now) {
  return {
    deadline() {
      return now() + ttlMs;
    },
    expired(deadline) {
      return now() >= deadline;
    }
  };
}

module.exports = { createClock };
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCache } = require('../src/cache');
const tick = () => new Promise(resolve => setImmediate(resolve));

function deferred() {
  let resolve;
  const promise = new Promise(done => { resolve = done; });
  return { promise, resolve };
}

test('invalidating during a load does not resurrect its stale value', { timeout: 2000 }, async () => {
  const gate = deferred();
  let calls = 0;
  const cache = createCache({
    now: () => 0,
    ttlMs: 100,
    load() {
      calls += 1;
      return calls === 1 ? gate.promise : 'fresh';
    }
  });
  const oldReader = cache.get('item');
  await tick();
  cache.invalidate('item');
  gate.resolve('stale');
  assert.equal(await oldReader, 'stale');
  assert.equal(await cache.get('item'), 'fresh');
  assert.equal(calls, 2);
});


