'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key; a flight may
// commit or unregister itself only while it is still the registered owner.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      const owns = () => pending.get(key) === promise;
      const promise = Promise.resolve().then(work).then(
        value => {
          if (owns()) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          if (owns()) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const d = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // 1. Old flight finishing after a newer one started must not detach the newer one or overwrite.
  {
    const gates = [d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].resolve('old');
    assert.equal(await a, 'old');
    const b2 = c.get('k'); // must join newer flight
    gates[1].resolve('new');
    assert.equal(await b, 'new'); assert.equal(await b2, 'new');
    assert.equal(calls, 2); assert.equal(await c.get('k'), 'new');
  }
  // 2. set wins; old completion doesn't restart TTL; after expiry a fresh load starts.
  {
    let t = 0; const g = d(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (calls++ === 0 ? g.promise : 'L2') });
    const a = c.get('k'); await tick();
    c.set('k', 'S'); t = 5; g.resolve('old');
    assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10;
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'L2'); assert.equal(calls, 2);
  }
  // 3. Rejection not cached, shared reason, retry works; sync throw and non-Error reason.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw 42; return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(r1.reason, 42); assert.equal(r2.reason, 42); assert.equal(calls, 1);
    assert.equal(await c.get('k'), 'ok');
  }
  // 4. Detached rejected flight must not detach newer flight.
  {
    const gates = [d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.clear();
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x'));
    await assert.rejects(a, /x/);
    const b2 = c.get('k'); gates[1].resolve('v');
    assert.equal(await b, 'v'); assert.equal(await b2, 'v'); assert.equal(calls, 2);
  }
  // 5. load invalidates/sets itself synchronously; self-read joins.
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) { c.invalidate(k); } return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(calls, 2);
    let self; let n = 0;
    const c2 = createCache({ now: () => 0, load: k => { n++; self = c2.get(k); return 'z'; } });
    assert.equal(await c2.get('k'), 'z'); assert.equal(await self, 'z'); assert.equal(n, 1);
    const c3 = createCache({ now: () => 0, load: k => { c3.set(k, 'S'); return 'L'; } });
    assert.equal(await c3.get('k'), 'L'); assert.equal(await c3.get('k'), 'S');
  }
  // 6. ttl 0 dedups unsettled, never reuses settled.
  {
    let calls = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(x, 1); assert.equal(y, 1); assert.equal(await c.get('k'), 2);
  }
  console.log('all scenarios ok');
})().catch(e => { console.error(e); process.exit(1); });
